          </label>
          <label>
            <input
              type="checkbox"
              checked={upper}
              onChange={e => setUpper(e.target.checked)}
            />
            대문자로 만들기
          </label>
          <p>안녕하세요, <b>{upper ? name.toUpperCase() : name}</b>님</p>
        </>
      )}
    </>
  );
}
```

